SELECT task.id FROM group_metadata_sync_task task WHERE task.group_link_id IN
#{groupLinkId}
ORDER BY task.id ASC

SELECT task.id FROM group_metadata_sync_task task FORCE INDEX (PRIMARY) WHERE task.tenant_id = #{tenantId} AND task.id IN
#{id}
ORDER BY task.id ASC FOR UPDATE

SELECT task.id, task.tenant_id, task.group_link_id, task.status, task.trigger_source, task.attempt_count, task.next_run_at, task.lease_until, task.execution_account_id, task.rerun_requested, task.current_command_id, task.requested_scope_mask, task.completed_scope_mask, task.candidate_cursor, task.result_deadline_at, task.last_started_at, task.last_success_at, task.last_error_code, task.last_error_message, task.created_at, task.updated_at, current_profile.member_snapshot_at AS memberSnapshotAt, COALESCE( NULLIF(TRIM(current_group.group_jid), ''), CASE WHEN link.link_url LIKE 'wa://group/%' THEN SUBSTRING(link.link_url, CHAR_LENGTH('wa://group/') + 1) ELSE NULL END ) AS groupJid, CASE WHEN link.origin = 4 AND link.link_url LIKE 'wa://group/%' AND NULLIF(TRIM(COALESCE( current_invite.invite_code, input_invite.invite_code )), '') IS NULL THEN TRUE ELSE FALSE END AS inviteRequired FROM group_metadata_sync_task task INNER JOIN group_link link ON link.tenant_id = task.tenant_id AND link.id = task.group_link_id AND link.deleted_at IS NULL LEFT JOIN wa_group current_group ON current_group.tenant_id = link.tenant_id AND current_group.id = link.group_id LEFT JOIN wa_group_profile current_profile ON current_profile.tenant_id = current_group.tenant_id AND current_profile.group_id = current_group.id LEFT JOIN wa_group_invite current_invite ON current_invite.tenant_id = current_profile.tenant_id AND current_invite.id = current_profile.current_invite_id LEFT JOIN wa_group_invite input_invite ON input_invite.tenant_id = link.tenant_id AND input_invite.id = link.group_invite_id WHERE task.status IN
#{status}
AND ( (task.next_run_at IS NOT NULL AND task.next_run_at <= #{now}) OR (task.status = #{periodicStatus} AND task.next_run_at IS NULL) )
ORDER BY CASE WHEN task.trigger_source = #{manualTrigger} THEN 0 WHEN task.last_success_at IS NULL THEN 1 WHEN task.status = 1 AND task.trigger_source IN (3, 4) THEN 2 ELSE 3 END ASC, task.next_run_at ASC, task.id ASC LIMIT #{limit}

mapper.update:
UPDATE group_metadata_sync_task
SET status = #{row.status},
    attempt_count = #{row.attemptCount},
    lease_until = #{row.leaseUntil},
    execution_account_id = #{row.executionAccountId},
    rerun_requested = FALSE,
    last_started_at = #{row.lastStartedAt},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status IN

    #{status}

  AND (
    (next_run_at IS NOT NULL AND next_run_at <= #{row.updatedAt})
    OR (status = #{periodicStatus} AND next_run_at IS NULL)
  )
  AND (
    SELECT running_count FROM (
      SELECT COUNT(*) AS running_count
      FROM group_metadata_sync_task
      WHERE tenant_id = #{row.tenantId}
        AND status = #{runningStatus}
    ) tenant_running
  ) < #{tenantConcurrency}
  AND (
    SELECT running_count FROM (
      SELECT COUNT(*) AS running_count
      FROM group_metadata_sync_task
      WHERE execution_account_id = #{row.executionAccountId}
        AND status = #{runningStatus}
    ) account_running
  ) < #{accountConcurrency}

UPDATE group_metadata_sync_task
SET status = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN 1
      ELSE #{row.status}
    END,
    attempt_count = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN 0
      ELSE #{row.attemptCount}
    END,
    next_run_at = CASE
      WHEN #{row.status} = 4 AND rerun_requested = TRUE THEN #{row.updatedAt}
      ELSE #{row.nextRunAt}
    END,
    lease_until = NULL,
    execution_account_id = NULL,
    rerun_requested = FALSE,
    last_success_at = COALESCE(#{row.lastSuccessAt}, last_success_at),
    last_error_code = #{row.lastErrorCode},
    last_error_message = #{row.lastErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status = #{runningStatus}

UPDATE group_metadata_sync_task
SET current_command_id = #{row.currentCommandId},
    requested_scope_mask = #{row.requestedScopeMask},
    completed_scope_mask = #{row.completedScopeMask},
    candidate_cursor = #{row.candidateCursor},
    result_deadline_at = #{row.resultDeadlineAt},
    lease_until = #{row.resultDeadlineAt},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status = #{runningStatus}
  AND current_command_id IS NULL

UPDATE group_metadata_sync_task
SET status = #{pendingStatus},
    next_run_at = #{row.nextRunAt},
    lease_until = NULL,
    execution_account_id = NULL,
    current_command_id = NULL,
    requested_scope_mask = 0,
    candidate_cursor = #{row.candidateCursor},
    result_deadline_at = NULL,
    last_error_code = #{row.lastErrorCode},
    last_error_message = #{row.lastErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND status = #{runningStatus}
  AND current_command_id = #{row.currentCommandId}

UPDATE group_metadata_sync_task SET status = #{row.status}, next_run_at = NULL, lease_until = NULL, execution_account_id = NULL, rerun_requested = FALSE, last_error_code = #{row.lastErrorCode}, last_error_message = #{row.lastErrorMessage}, updated_at = #{row.updatedAt} WHERE id = #{row.id} AND tenant_id = #{row.tenantId} AND status IN
#{status}
AND NOT EXISTS ( SELECT 1 FROM group_link group_handle INNER JOIN wa_account_group_binding binding ON binding.tenant_id = group_handle.tenant_id AND binding.group_id = group_handle.group_id INNER JOIN wa_group_participant self_participant ON self_participant.tenant_id = binding.tenant_id AND self_participant.group_id = binding.group_id AND self_participant.id = binding.participant_id AND self_participant.presence_status = 1 INNER JOIN account a ON a.tenant_id = binding.tenant_id AND a.id = binding.account_id AND a.deleted_at IS NULL AND a.protocol_account_id IS NOT NULL AND a.protocol_account_id != '' AND a.ws_phone IS NOT NULL AND a.ws_phone != '' INNER JOIN account_state s ON s.tenant_id = a.tenant_id AND s.account_id = a.id AND s.login_state = #{onlineLoginState} AND s.account_state IN #{accountState} WHERE group_handle.tenant_id = #{row.tenantId} AND group_handle.id = #{row.groupLinkId} AND group_handle.deleted_at IS NULL )

mapper.insert:
INSERT INTO group_metadata_sync_task (
  group_link_id, status, trigger_source, attempt_count, next_run_at,
  rerun_requested, completed_scope_mask, created_at, updated_at
) VALUES

  (
    #{row.groupLinkId}, #{row.status}, #{row.triggerSource}, #{row.attemptCount},
    #{row.nextRunAt}, FALSE, #{row.completedScopeMask}, #{row.createdAt}, #{row.updatedAt}
  )

ON DUPLICATE KEY UPDATE
  trigger_source = CASE WHEN status = #{deferredStatus}
    THEN VALUES(trigger_source) ELSE trigger_source END,
  attempt_count = CASE WHEN status = #{deferredStatus} THEN 0 ELSE attempt_count END,
  next_run_at = CASE WHEN status = #{deferredStatus}
    THEN VALUES(next_run_at) ELSE next_run_at END,
  lease_until = CASE WHEN status = #{deferredStatus} THEN NULL ELSE lease_until END,
  execution_account_id = CASE WHEN status = #{deferredStatus}
    THEN NULL ELSE execution_account_id END,
  current_command_id = CASE WHEN status = #{deferredStatus}
    THEN NULL ELSE current_command_id END,
  requested_scope_mask = CASE WHEN status = #{deferredStatus}
    THEN 0 ELSE requested_scope_mask END,
  candidate_cursor = CASE WHEN status = #{deferredStatus}
    THEN 0 ELSE candidate_cursor END,
  result_deadline_at = CASE WHEN status = #{deferredStatus}
    THEN NULL ELSE result_deadline_at END,
  rerun_requested = CASE WHEN status = #{deferredStatus}
    THEN FALSE ELSE rerun_requested END,
  last_error_code = CASE WHEN status = #{deferredStatus}
    THEN NULL ELSE last_error_code END,
  last_error_message = CASE WHEN status = #{deferredStatus}
    THEN NULL ELSE last_error_message END,
  updated_at = CASE WHEN status = #{deferredStatus}
    THEN VALUES(updated_at) ELSE updated_at END,
  status = CASE WHEN status = #{deferredStatus} THEN #{pendingStatus} ELSE status END
